using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Shapes;
using Microsoft.Win32;
namespace ArchiveReader;
public partial class InterchangeWindow:Window
{
 readonly string page;readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;CancellationTokenSource? work;bool busy;
 readonly TextBox file=new(){IsReadOnly=true},metadata=new(){IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,Height=140},text=new(){IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,Height=110};readonly ListBox rows=new(){Height=180,DisplayMemberPath="Label"};readonly CheckBox clipping=new(){Content=new TextBlock{Text="Підтверджую обрізання малих виходів за межі зображення",TextWrapping=TextWrapping.Wrap}},identity=new(){Content=new TextBlock{Text="Я перевірив, що XML відповідає саме цій сторінці",TextWrapping=TextWrapping.Wrap}},confirm=new(){Content=new TextBlock{Text="Додати лише нові неперевірені ділянки",TextWrapping=TextWrapping.Wrap}};readonly Image image=new();readonly Canvas overlay=new();readonly Grid source=new();readonly Button apply=new(){Content="Додати ділянки",IsEnabled=false,Padding=new Thickness(10,5,10,5),HorizontalAlignment=HorizontalAlignment.Left};JsonObject? preview;
 static string T(string s)=>Localizer.Text(s);Task<JsonNode> Call(string c,JsonObject? a=null)=>worker(c,a,work?.Token??default);
 public InterchangeWindow(string page,Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker){this.page=page;this.worker=worker;InitializeComponent();Build();Loaded+=async(_,_)=>{Localizer.Apply(this,Localizer.Language);await Run(async()=>{var r=await Call("render",new(){["id"]=page,["whole"]=true,["full"]=true,["preprocess"]="original"});ShowImage(r["path"]!.ToString(),r["width"]!.GetValue<int>(),r["height"]!.GetValue<int>());if(Environment.GetCommandLineArgs().Contains("--smoke-interchange")){var xml=Environment.GetEnvironmentVariable("ARCHIVEREADER_SMOKE_XML");if(!string.IsNullOrEmpty(xml)){file.Text=xml;await Preview();}ContentGrid.IsEnabled=true;SmokeCapture.Save(this,"interchange-ui","preview.png");Close();}});};Closing+=(_,_)=>work?.Cancel();}
 void Label(Panel panel,string label)=>panel.Children.Add(new TextBlock{Text=T(label),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,5)});
 void Button(Panel panel,string label,Func<Task> action){var b=new Button{Content=T(label),Padding=new Thickness(10,5,10,5),Margin=new Thickness(0,3,6,3),HorizontalAlignment=HorizontalAlignment.Left};b.Click+=async(_,_)=>await Run(action);panel.Children.Add(b);}
 void Build(){ContentGrid.ColumnDefinitions.Add(new(){Width=new GridLength(460)});ContentGrid.ColumnDefinitions.Add(new());var settings=new StackPanel{Margin=new Thickness(0,0,12,0)};Label(settings,"Оберіть XML однієї сторінки. Перевірте розміри, джерело, текст і контури. Наявна розмітка, записи та перевірені тексти залишаться без змін.");settings.Children.Add(file);Button(settings,"Вибрати XML і переглянути",Choose);settings.Children.Add(metadata);settings.Children.Add(rows);settings.Children.Add(text);settings.Children.Add(identity);settings.Children.Add(clipping);settings.Children.Add(confirm);apply.Click+=async(_,_)=>await Run(ApplyImport);settings.Children.Add(apply);var exports=new WrapPanel();Button(exports,"Експорт PAGE XML",()=>Export("page"));Button(exports,"Експорт ALTO XML",()=>Export("alto"));settings.Children.Add(exports);Label(settings,"Блакитні контури — текстові ділянки; помаранчеві — базові лінії з XML. Відсутні базові лінії не вигадуються. Експорт підтримує текстові блоки й рядки; складна ієрархія не переноситься повністю.");var scroll=new ScrollViewer{Content=settings,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};ContentGrid.Children.Add(scroll);source.Children.Add(image);source.Children.Add(overlay);var view=new ScrollViewer{Content=new Viewbox{Child=source,Stretch=Stretch.Uniform},HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetColumn(view,1);ContentGrid.Children.Add(view);rows.SelectionChanged+=(_,_)=>{if(rows.SelectedItem is GenealogyRow row)text.Text=row.Data["text"]?.ToString()??"";};}
 async Task Run(Func<Task> action){if(busy)return;busy=true;work=new();ContentGrid.IsEnabled=false;try{Status.Text="";await action();if(string.IsNullOrWhiteSpace(Status.Text))Status.Text=T("Готово");}catch(OperationCanceledException){Status.Text=T("Обробку зупинено.");}catch(Exception ex){Status.Text=T(ex.Message);SmokeCapture.Fail(ex);}finally{ContentGrid.IsEnabled=true;work.Dispose();work=null;busy=false;}}
 void ShowImage(string path,int width,int height){var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.UriSource=new Uri(path);bitmap.EndInit();bitmap.Freeze();image.Source=bitmap;source.Width=width;source.Height=height;overlay.Width=width;overlay.Height=height;}
 async Task Choose(){var dialog=new OpenFileDialog{Filter="PAGE / ALTO XML|*.xml"};if(dialog.ShowDialog()!=true)return;preview=null;apply.IsEnabled=false;identity.IsChecked=false;clipping.IsChecked=false;confirm.IsChecked=false;file.Text=dialog.FileName;await Preview();}
 string Reason(string key)=>T(key switch{"dimensions_mismatch"=>"Розміри XML не відповідають зображенню","source_sha_mismatch"=>"Контрольна сума джерела не збігається","image_sha_mismatch"=>"Контрольна сума зображення не збігається","page_identity_mismatch"=>"Ідентифікатор сторінки не збігається",_=>key});
 async Task Preview(){preview=(await Call("interchange_preview",new(){["id"]=page,["path"]=file.Text})).AsObject();var parsed=preview["parsed"]!;var target=preview["target"]!;ShowImage(target["path"]!.ToString(),target["width"]!.GetValue<int>(),target["height"]!.GetValue<int>());var blocked=preview["blocked"]!.AsArray();metadata.Text=T("Цільова сторінка")+": "+target["name"]+" · "+(target["frame"]!.GetValue<int>()+1)+"\n"+T("Зображення в XML")+": "+parsed["image_filename"]+" · "+parsed["width"]+" × "+parsed["height"]+"\n"+T("Розмір цілі")+": "+target["width"]+" × "+target["height"]+"\nSHA-256 XML: "+preview["xml_sha256"]+"\n"+(blocked.Count>0?string.Join("\n",blocked.Select(x=>Reason(x!.ToString()))):T(preview["identity_confirmation_required"]!.GetValue<bool>()?"Відповідність сторінки потребує ручного підтвердження":"Джерело та сторінка збігаються за контрольними сумами"));metadata.Text+="\n"+T("Обрізаних контурів")+": "+parsed["rows"]!.AsArray().Count(n=>n!["geometry_clipped"]!.GetValue<bool>())+" · "+T("Створених ідентифікаторів")+": "+parsed["rows"]!.AsArray().Count(n=>n!["external_id_generated"]!.GetValue<bool>());rows.ItemsSource=parsed["rows"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["external_id"]+" · "+T(n["kind"]!.ToString()=="line"?"Рядок":"Блок")+" · "+T("Порядок")+": "+(n["reading_order"]?.ToString()??T("не заданий"))+"\n"+n["text"])).ToList();rows.SelectedItem=rows.Items.Cast<GenealogyRow>().FirstOrDefault(r=>!string.IsNullOrWhiteSpace(r.Data["text"]?.ToString()))??rows.Items.Cast<GenealogyRow>().FirstOrDefault();apply.IsEnabled=blocked.Count==0;Draw(parsed["rows"]!.AsArray(),target["width"]!.GetValue<int>(),target["height"]!.GetValue<int>());}
 void Draw(JsonArray data,int width,int height){overlay.Children.Clear();foreach(var row in data){foreach(var key in new[]{"polygon","baseline"}){if(row?[key] is not JsonArray pts)continue;var points=new PointCollection(pts.Select(n=>new Point(n![0]!.GetValue<double>()*width,n[1]!.GetValue<double>()*height)));if(key=="polygon")overlay.Children.Add(new Polygon{Points=points,Stroke=Brushes.DeepSkyBlue,StrokeThickness=Math.Max(1,width/500.0),Fill=Brushes.Transparent});else overlay.Children.Add(new Polyline{Points=points,Stroke=Brushes.DarkOrange,StrokeThickness=Math.Max(1,width/400.0)});}}}
 async Task ApplyImport(){if(preview==null)return;var result=await Call("interchange_apply",new(){["id"]=page,["token"]=preview["token"]!.ToString(),["confirm"]=confirm.IsChecked==true,["confirm_identity"]=identity.IsChecked==true,["confirm_clipping"]=clipping.IsChecked==true});apply.IsEnabled=false;Status.Text=T("Додано неперевірених ділянок")+": "+result["added"];}
 async Task Export(string format){var r=await Call("interchange_export",new(){["id"]=page,["format"]=format});Status.Text=T("Експорт збережено разом із зображенням і походженням")+": "+r["path"];}
}
